const results = [];
for (const item of $input.all()) {
  const json = item.json;
  // 1. Filter Tipe Transaksi
  const tipe = json['Tipe Transaksi'];
  if (tipe !== 'Pembayaran' && tipe !== 'Pengeluaran' && tipe !== 'Penerimaan') {
    continue;
  }

  // 2. Bersihkan Tanggal (DD/MM/YYYY -> YYYY-MM-DD)
  const rawDate = (json['Tanggal Transaksi'] || '').toString().trim();
  const dateParts = rawDate.split('/');
  if (dateParts.length !== 3) continue;
  const cleanDate = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;

  // 3. Bersihkan Nominal (Hapus Rp, titik, koma)
  const rawAmount = (json['Jumlah (IDR)'] || '0').toString();
  const cleanAmount = rawAmount.replace(/[^0-9]/g, '');

  // 4. Buat Match Key (Hanya pakai Nominal agar cocok dengan data Bank)
  const matchKey = cleanAmount;

  results.push({
    json: {
      ...json,
      cleanDate: cleanDate,
      cleanAmount: cleanAmount,
      match_key: matchKey,
      sumber: 'Internal'
    }
  });
}
return results;

const results = [];
for (const item of $input.all()) {
  const json = item.json;

  // 1. Ambil data mentah
  const rawDate = (json['Tanggal Bank'] || '').toString().trim();
  const rawAmount = (json['Jumlah (IDR)'] || '0').toString();

  // 2. Bersihkan Nominal (Hanya ambil angka, buang titik/koma)
  const cleanAmount = rawAmount.replace(/[^0-9]/g, '');

  // 3. Tangani Tanggal yang Formatnya Campur Aduk
  let cleanDate = rawDate;
  const parts = rawDate.split('/');

  if (parts.length === 3) {
    const p1 = parseInt(parts[0]);
    const p2 = parseInt(parts[1]);
    const year = parts[2];

    // Logika: Jika angka pertama > 12, berarti itu pasti Tanggal (DD/MM/YYYY)
    if (p1 > 12) {
      const day = parts[0].padStart(2, '0');
      const month = parts[1].padStart(2, '0');
      cleanDate = `${year}-${month}-${day}`;
    } 
    // Jika angka kedua > 12, berarti angka pertama pasti Bulan (MM/DD/YYYY)
    else if (p2 > 12) {
      const month = parts[0].padStart(2, '0');
      const day = parts[1].padStart(2, '0');
      cleanDate = `${year}-${month}-${day}`;
    } 
    // Jika ambigu (keduanya <= 12), asumsikan format aslinya DD/MM/YYYY (sesuai baris awal CSV)
    else {
      const day = parts[0].padStart(2, '0');
      const month = parts[1].padStart(2, '0');
      cleanDate = `${year}-${month}-${day}`;
    }
  }

  // 4. Buat Match Key (KITA HANYA GUNAKAN NOMINAL SAJA)
  // Karena tanggal CSV berantakan, kita kunci pakai nominalnya saja.
  const matchKey = cleanAmount; 

  results.push({
    json: {
      ...json,
      cleanDate: cleanDate, // Tetap simpan tanggal untuk laporan
      cleanAmount: cleanAmount,
      match_key: matchKey,  // Kunci pencocokan hanya pakai Nominal
      sumber: 'Bank'
    }
  });
}
return results;

const items = $input.all();
const grouped = {};

// 1. Kelompokkan berdasarkan match_key
for (const item of items) {
  const key = item.json.match_key;
  if (!grouped[key]) {
    grouped[key] = { sources: [], details: [] };
  }
  grouped[key].sources.push(item.json.sumber);
  grouped[key].details.push(item.json);
}

// 2. Bangun hasil analisis
const results = [];
for (const [key, group] of Object.entries(grouped)) {
  const hasInternal = group.sources.includes('Internal');
  const hasBank = group.sources.includes('Bank');

  let status = '';
  let keterangan = '';

  if (hasInternal && hasBank) {
    status = 'MATCHED';
    keterangan = '✅ Data klop (Cocok).';
  } else if (hasInternal && !hasBank) {
    status = 'MISSING IN BANK';
    keterangan = '⚠️ Ada di Internal, tapi tidak ada di Bank.';
  } else if (!hasInternal && hasBank) {
    status = 'UNRECORDED INTERNAL';
    keterangan = '🚨 Ada di Bank, tapi tidak tercatat di Internal.';
  }

  // Ambil data internal atau bank untuk laporan
  const detail = group.details[0];

  results.push({
    json: {
      Tanggal: detail.cleanDate,
      Nominal: detail.cleanAmount,
      Status: status,
      Keterangan: keterangan,
      Ref_Internal: group.details.find(d => d.sumber === 'Internal')?.['ID Transaksi'] || 'N/A',
      Ref_Bank: group.details.find(d => d.sumber === 'Bank')?.['ID Transaksi Bank'] || 'N/A',
      Desc: detail['Deskripsi'] || '-'
    }
  });
}
return results;
